import sys

data = sys.stdin.read().split()
n, m, src, dest = int(data[0]), int(data[1]), int(data[2]), int(data[3])
if src == dest:
    print(0)
    sys.exit()
adj = [[] for _ in range(n)]
pos = 4
for _ in range(m):
    u = int(data[pos]); v = int(data[pos + 1]); w = int(data[pos + 2])
    pos += 3
    adj[u].append((v, w))
    adj[v].append((u, w))
dist = {(src, None): 0}
changed = True
while changed:
    changed = False
    for (v, lw), d in list(dist.items()):
        for x, w in adj[v]:
            nd = d + (1 if lw is not None and lw != w else 0)
            key = (x, w)
            if key not in dist or nd < dist[key]:
                dist[key] = nd
                changed = True
best = None
for (v, lw), d in dist.items():
    if v == dest and (best is None or d < best):
        best = d
print(-1 if best is None else best)

